void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

  vec2 uv = fragCoord/iResolution.xy;
  uv.y = 1. - uv.y;
  float u_time = iTime / 10.;

  vec3 rgb2;
  vec3 rgb3;

  float y = (uv.y - 0.5) * 2.0;

  float x = uv.x - 1.0/2.0;
  float sy = -((uv.y - 0.5)*10.0);
  float ty = tan( (exp( sy) * 35.0) + u_time * 50.0);
  float tx = sin( ( x  * .1/y * 200.0) );



  if( uv.y < 0.5  ) {
      float y2 = uv.y * 2.0;
      float rFact = (cos( u_time *2.1)+1.0) / 3.0;
      float gFact = (sin( u_time *1.)+1.0) / 5.0;
      float bFact = (sin( u_time *.4)+1.0) / 2.0;

      rgb3 = vec3(y2 * rFact,y2 *gFact, y2*bFact);
    }
  else {

      if( ty < 0.0) {
          rgb2 = vec3(0.2,.5,.2);
      }
      else {
          rgb2 = vec3(0.2,1.0,0.2);
      }

      if( tx < 0.0) {
          rgb3 = (vec3(.3,.5,.3) + rgb2) / 2.0;
      }
      else {
          rgb3 = (vec3(0.8,1.0,.4) + rgb2) / 2.0;
      }

      rgb3 = ((rgb3 * y) * .8) + (rgb3 * .2);
  }
  fragColor = vec4(rgb3, 1.0);

}
